{"file_path":"src/parser.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parse a build graph from the raw text of standard input.
 *
 * Returns `{ tasks, deps }` where `tasks` maps a task name to its cost and
 * `deps` maps a task name to the `Set` of names it directly depends on
 * (present only for names that appeared as the head of a `dep` line).
 *
 * Throws a `CliError` (exit code 2) on the first malformed line, and again
 * after the whole input is read if a `dep` line names a task that no `task`
 * line ever declares.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  // Every name used on a dep line, in the order it is first encountered,
  // for the "unknown task" check that runs once parsing finishes.
  const usedNames = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costText)) {
        throw new CliError(`error: line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, Number.parseInt(costText, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const name = words[1]
      const dependencies = words.slice(2)
      usedNames.push(name)
      for (const dependency of dependencies) usedNames.push(dependency)

      let set = deps.get(name)
      if (!set) {
        set = new Set()
        deps.set(name, set)
      }
      for (const dependency of dependencies) set.add(dependency)
    } else {
      throw new CliError(`error: line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) throw new CliError(`error: unknown task ${name}`, 2)
  }

  return { tasks, deps }
}
"}

