/**
 * Depth-first search for a cycle, starting from each task in ascending name
 * order and walking each task's dependencies in ascending name order. Throws
 * a `CliError` (exit code 3) describing the first cycle found, running from
 * the re-entered task through the search stack and back to itself.
 */
export function checkForCycle(tasks, deps) {
  const visited = new Set()
  const stack = []
  const onStack = new Set()

  const visit = (name) => {
    if (onStack.has(name)) {
      const start = stack.indexOf(name)
      const cycle = [...stack.slice(start), name]
      throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
    }
    if (visited.has(name)) return
    visited.add(name)
    stack.push(name)
    onStack.add(name)
    const dependencies = [...(deps.get(name) || [])].sort()
    for (const dependency of dependencies) visit(dependency)
    stack.pop()
    onStack.delete(name)
  }

  for (const name of [...tasks.keys()].sort()) visit(name)
}

/**
 * Compute each task's start, finish and depth (wave). A task with no
 * dependencies starts at 0; otherwise it starts when the last of its
 * dependencies finishes. Depth is the number of dependency "hops" back to a
 * task with no dependencies. Assumes the graph is acyclic.
 */
export function computeTimings(tasks, deps) {
  const timings = new Map()

  const resolve = (name) => {
    const cached = timings.get(name)
    if (cached) return cached
    const dependencies = [...(deps.get(name) || [])]
    let start = 0
    let depth = 0
    for (const dependency of dependencies) {
      const dependencyTiming = resolve(dependency)
      if (dependencyTiming.finish > start) start = dependencyTiming.finish
      if (dependencyTiming.depth + 1 > depth) depth = dependencyTiming.depth + 1
    }
    const cost = tasks.get(name)
    const timing = { start, finish: start + cost, depth }
    timings.set(name, timing)
    return timing
  }

  for (const name of tasks.keys()) resolve(name)
  return timings
}

/**
 * The cost of the longest chain that begins at the task, counting its own
 * cost and then the costs of the dependencies below it down to a task that
 * nothing depends on. Assumes the graph is acyclic.
 */
export function computePriorities(tasks, deps) {
  const priorities = new Map()

  const resolve = (name) => {
    const cached = priorities.get(name)
    if (cached !== undefined) return cached
    const dependencies = [...(deps.get(name) || [])]
    let best = 0
    for (const dependency of dependencies) {
      const dependencyPriority = resolve(dependency)
      if (dependencyPriority > best) best = dependencyPriority
    }
    const priority = tasks.get(name) + best
    priorities.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) resolve(name)
  return priorities
}
"}

