/**
 * Simulate the build graph on `workerCount` workers. At each instant, while
 * a worker is free and some task is ready (every dependency has already
 * finished), the ready task with the greatest priority (ties broken by
 * ascending name) starts on the free worker with the smallest index. Time
 * then advances to the next instant a worker frees up. Assumes the graph is
 * acyclic.
 */
export function packWorkers(tasks, deps, workerCount) {
  const priorities = computePriorities(tasks, deps)
  const names = [...tasks.keys()]
  const remaining = new Set(names)
  const finish = new Map()
  const freeAt = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])

  const isReady = (name) => {
    for (const dependency of tasks.has(name) ? [] : []) void dependency
    return true
  }

  const dependenciesOf = (name) => [...(deps.get(name) || [])]

  let time = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      const freeWorkers = []
      for (let i = 0; i < workerCount; i += 1) if (freeAt[i] <= time) freeWorkers.push(i)
      if (freeWorkers.length === 0) break

      const ready = []
      for (const name of remaining) {
        const dependencies = dependenciesOf(name)
        const allFinished = dependencies.every((dependency) => finish.get(dependency) <= time)
        if (allFinished) ready.push(name)
      }
      if (ready.length === 0) break

