/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parser.js'
import { checkForCycle, computeTimings } from './graph.js'
import { packWorkers } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function readMode(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: Number.parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function formatWaves(tasks, timings) {
  const byDepth = new Map()
  for (const [name, timing] of timings) {
    let names = byDepth.get(timing.depth)
    if (!names) {
      names = []
      byDepth.set(timing.depth, names)
    }
    names.push(name)
  }

  const maxDepth = byDepth.size === 0 ? -1 : Math.max(...byDepth.keys())
  const lines = []
  for (let depth = 0; depth <= maxDepth; depth += 1) {
    const names = (byDepth.get(depth) || []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  const total = totalOf(timings)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(timings) {
  const lines = []
  for (const name of [...timings.keys()].sort()) {
    const { start, finish, depth } = timings.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  lines.push(`total ${totalOf(timings)}`)
  return lines.join('\n') + '\n'
}

function totalOf(timings) {
  let total = 0
  for (const timing of timings.values()) if (timing.finish > total) total = timing.finish
  return total
}

function formatPack(runs, makespan) {
  const lines = runs.map((run, index) => {
    const entries = run.map(({ name, start, finish }) => ` ${name}@${start}-${finish}`).join('')
    return `worker ${index}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const { mode, workers } = readMode(argv)

  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  checkForCycle(tasks, deps)

  if (mode === 'waves') {
    process.stdout.write(formatWaves(tasks, computeTimings(tasks, deps)))
  } else if (mode === 'explain') {
    process.stdout.write(formatExplain(computeTimings(tasks, deps)))
  } else {
    const { runs, makespan } = packWorkers(tasks, deps, workers)
    process.stdout.write(formatPack(runs, makespan))
  }
}

try {
  main()
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(error.message + '\n')
    process.exit(error.exitCode)
  }
  throw error
}
"}

